/* Residual learning: distinguish the training problem, then trace both paths. */
(()=>{
  const lesson=lessons.find(item=>item.id==='cnn');
  if(!lesson)return;
  const firstSection=lesson.sections.length;
  lesson.time=Math.max(lesson.time||0,120);
  lesson.desc='从卷积的局部乘加与通道形状，走到 LeNet、AlexNet、VGG 和 ResNet；用图解与交互理解感受野、参数和深层网络训练。';
  lesson.goals.push('区分过拟合、梯度消失和深层普通网络的优化退化。','用输入、残差分支、相加与激活追踪一个残差块，并检查两条路径的张量形状。','说明残差连接改善优化的思路与边界，辨认 BasicBlock 和瓶颈块。');
  lesson.sections.push(
    {title:'17. 网络加深后：先分清三种训练问题',paragraphs:[
      'VGG 展示了增加深度的价值，继续堆层却不一定更容易训练。看到深层网络效果下降，先区分发生在哪里：是训练数据拟合很好、独立数据表现变差，还是连训练误差也高于可比的浅层模型？两种现象需要不同的解释。',
      '过拟合关注泛化：模型对训练样本拟合很好，却没有在独立数据上取得相应效果。它与模型容量、数据量、标签噪声、正则化和分布等有关，不能只用“参数多”来定义。梯度消失关注反向传播：连乘的局部导数可能让较早层收到的梯度很小，使学习缓慢；它不表示所有较早层一定完全不更新，权重、激活、归一化和优化器都会影响实际更新。',
      'ResNet 论文中的网络退化，是加深普通网络后，训练误差反而更高的优化现象，因而不能归咎于过拟合。论文在带 BN 的普通网络中仍观察到退化，并检查到正常的梯度幅度，所以不能简单写成“梯度消失必然导致这里的退化”。公平比较要保持数据和训练协议可比，再结合训练曲线、验证表现与逐层梯度判断。'
    ]},
    {title:'18. 残差连接：保留一条直路，再学习修正',paragraphs:[
      '设希望某组层完成的映射为 H(x)。残差学习把它改写成 H(x)=x+F(x)，其中 F(x)=H(x)−x。可以把 x 想成当前已有的特征，F(x) 是这组层学到的修正。这里的“残差”是相对块输入的特征变化，不是损失函数，也不要求另行标注一份残差答案；整个模型仍用任务损失端到端训练。',
      '一个基础残差块有两条路：主路径经过卷积、BN 和激活得到 F(x)；捷径在形状相同时直接传递 x。两条路在末端逐元素相加。这里的 x 是当前块的输入特征，不一定是最初的原图，也不是一套冻结的浅层网络。原版 ResNet 的常见块在相加后还有 ReLU，所以应分清相加前后：s=x+F(x)，输出 y=ReLU(s)。',
      '如果 F(x)=0，相加结果 s=x，这让表示恒等映射更直接。但它只是结构上容易表达的一种解，不是训练效果的保底承诺。对带块末 ReLU 的版本，负数仍会被截掉；投影捷径也会改变输入。残差分支会实际学习有用变化，已有层也会一起更新，并非新增层永远不学新特征。',
      '从相加前的标量例子 s=x+F(x) 看，局部导数是 ds/dx=1+F′(x)，反向信号因此多了一条来自恒等捷径的直接通路。它有助于传播与优化，但总梯度并不恒为 1；分支可以相互抵消，也可能放大。真实块若有末端 ReLU，还要乘它的局部导数；多通道情形对应 I+J_F。下面的简化实验特意展示这些边界。'
    ]},
    {title:'19. 把残差块接对：形状、瓶颈与深度边界',paragraphs:[
      '逐元素相加要求两条路径在对应位置上形状一致。相同尺寸的基础块可直接用恒等捷径；若主路径把空间减半并增加通道，捷径也要对齐。常见做法是 1×1 卷积配合合适步幅和 BN，得到 S(x)，再计算 F(x)+S(x)。恒等捷径本身没有可学习参数，投影捷径则有。Add 不会把通道拼起来，Concat 才会沿通道轴拼接；实现时不要靠广播掩盖设计中的形状错误。',
      'ResNet-18/34 常用两层 3×3 卷积的 BasicBlock；ResNet-50/101/152 常用 1×1 → 3×3 → 1×1 的瓶颈块。瓶颈先调整通道宽度，再在较窄表示上做 3×3 空间计算，最后扩展通道。块的输出宽度、是否下采样和具体实现必须一起看；Torchvision 的某些瓶颈下采样位置与原论文版本不同。',
      '原论文在 ImageNet 上研究了 152 层模型，也在 CIFAR-10 上探索了 1202 层；后者测试表现反而弱于 110 层模型。优化更容易不等于可以无限加深并持续提高泛化。选择深度还要看数据、训练、显存、运算和延迟。ResNet 的贡献是让深层网络更易优化，并不是消除了所有梯度问题、过拟合与资源限制。'
    ]}
  );
  lesson.keypoints.push('网络退化的关键信号是更深普通网络的训练误差也更高，不能和过拟合或梯度消失直接画等号。','残差学习让主路径学习 F(x)，再与块输入 x 或投影 S(x) 逐元素相加；这不是 Concat。','相加前的恒等残差块导数含 I+J_F；直接通路有助于优化，但不保证梯度永远为 1。','相加要求形状对齐；1×1 投影可以匹配通道与空间步幅，并会引入可学习参数。','BasicBlock 常含两层 3×3；瓶颈块常用 1×1、3×3、1×1，具体版本需查看实现。','残差网络仍可能过拟合；更深不保证训练结果或独立数据效果更好。');
  const sources=[
    {url:'https://www.cv-foundation.org/openaccess/content_cvpr_2016/papers/He_Deep_Residual_Learning_CVPR_2016_paper.pdf',label:'He 等：Deep Residual Learning for Image Recognition（CVPR 2016，退化、捷径与深度实验）'},
    {url:'https://arxiv.org/abs/1603.05027',label:'He 等：Identity Mappings in Deep Residual Networks（恒等通路与预激活分析）'},
    {url:'https://docs.pytorch.org/vision/main/_modules/torchvision/models/resnet.html',label:'Torchvision ResNet 源码：BasicBlock、Bottleneck 与投影捷径'}
  ];
  lesson.sources=[...(lesson.sources||[]),...sources.filter(s=>!(lesson.sources||[]).some(x=>x.url===s.url))];
  const previous=window.lessonPlaygrounds||{};
  const esc=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const diagnoses={
    overfit:{label:'过拟合',title:'训练拟合很好，独立数据没有跟上',copy:'关注训练与独立数据的表现差距。检查划分、分布、数据量与正则化；参数数量本身不能完成诊断。',axis:'误差',lines:[{name:'训练误差',color:'purple',points:[92,65,42,29,22,18]},{name:'验证误差',color:'green',points:[97,73,61,65,76,91]}],note:'这组简图表达训练与验证表现逐渐分离，不对应某个模型的实测数值。'},
    vanish:{label:'梯度消失',title:'反向信号到较早层时可能越来越小',copy:'链式法则会连乘局部导数。需实际检查梯度范数与参数更新；不能仅凭验证曲线断定梯度消失，也不能断言浅层参数必然完全不更新。',axis:'梯度幅度',lines:[],note:'示意从靠近输出到靠近输入的梯度衰减；真实网络不一定单调变化。'},
    degrade:{label:'网络退化',title:'加深后，连训练误差也更高',copy:'在可比设置下，深层普通网络比浅层网络更难优化。原论文的 BN 网络即使梯度幅度正常也会退化，因此它与梯度消失不是同义词。',axis:'训练误差',lines:[{name:'浅层普通网络',color:'green',points:[99,65,43,27,19,15]},{name:'深层普通网络',color:'purple',points:[104,82,69,59,51,47]}],note:'比较的是两种深度的训练误差；曲线仅作现象示意，不是原论文数据重绘。'}
  };
  function heading(kicker,title,copy){return '<div class="vg-panel-head"><div><span>'+kicker+'</span><h4>'+title+'</h4></div><p>'+copy+'</p></div>'}
  function diagnoseMarkup(){return '<section class="vgg-playground resnet-playground" data-resnet="diagnose"><div class="vg-panel">'+heading('01 · DIAGNOSE','先看清问题发生在哪里','点击三个概念，对照观察对象。')+'<div class="vg-model-switch" role="group" aria-label="选择训练问题">'+Object.entries(diagnoses).map(([key,item])=>'<button type="button" data-rn-diagnosis="'+key+'" aria-pressed="'+String(key==='overfit')+'">'+item.label+'</button>').join('')+'</div><div class="rn-diagnose-layout"><div class="rn-chart" data-rn-chart></div><div class="rn-explanation" aria-live="polite"><h5 data-rn-diagnosis-title></h5><p data-rn-diagnosis-copy></p></div></div><p class="vg-caption" data-rn-diagnosis-note></p></div></section>'}
  function chartMarkup(item){
    if(!item.lines.length)return '<div class="rn-gradient-bars"><span>梯度幅度 · 示意</span>'+[100,54,24,9,3].map((n,i)=>'<div><small>'+(i===0?'靠近输出':i===4?'靠近输入':'中间层')+'</small><i style="--bar:'+n+'%"></i></div>').join('')+'</div>';
    return '<svg viewBox="0 0 380 185" role="img" aria-label="'+esc(item.title)+'的示意曲线"><path class="rn-axis" d="M38 27V150H360"/><text x="10" y="15">'+item.axis+' ↑</text><text x="271" y="174">训练进程 →</text>'+item.lines.map(line=>'<path class="rn-line rn-'+line.color+'" d="'+line.points.map((v,i)=>(i?'L':'M')+(40+i*62)+' '+(145-v)).join(' ')+'"/>').join('')+item.lines.map((line,i)=>'<text class="rn-label-'+line.color+'" x="44" y="'+(166+i*13)+'">'+esc(line.name)+'</text>').join('')+'</svg>';
  }
  function blockSvg(){return '<svg viewBox="0 0 520 265" class="rn-block-svg" role="img" aria-label="输入分成残差主路径和恒等捷径，相加后接 ReLU"><defs><marker id="rn-arrow" markerWidth="7" markerHeight="7" refX="5" refY="3" orient="auto"><path d="M0 0L6 3 0 6" fill="none" stroke="#8f839e"/></marker></defs><path class="rn-wire" d="M260 28V47H150V67M150 108V126M150 165V191H260M260 47H396V191H280M270 207V230"/><rect x="214" y="8" width="112" height="31" rx="5"/><text x="270" y="28" data-rn-svg-x>x = 2</text><rect x="77" y="67" width="147" height="42" rx="5"/><text x="150" y="85">Conv → BN → ReLU</text><text x="150" y="100">主路径第 1 层</text><rect x="77" y="126" width="147" height="40" rx="5"/><text x="150" y="143">Conv → BN</text><text x="150" y="158" data-rn-svg-r>F(x) = −0.5</text><text x="399" y="107">恒等捷径</text><text x="399" y="125">保留当前块输入 x</text><circle cx="270" cy="191" r="17"/><text x="270" y="197" class="rn-plus">+</text><text x="343" y="196" data-rn-svg-s>s = 1.5</text><rect x="200" y="231" width="140" height="29" rx="5"/><text x="270" y="250" data-rn-svg-y>ReLU(s) = 1.5</text></svg>'}
  function blockMarkup(){return '<section class="vgg-playground resnet-playground" data-resnet="block"><div class="vg-panel">'+heading('02 · RESIDUAL BLOCK','两条路走到同一个加号','用标量代表一个特征位置，观察正负修正。')+'<div class="rn-block-layout">'+blockSvg()+'<div class="rn-controls"><label>输入特征 x <output data-rn-x-out>2</output><input type="range" min="-3" max="3" step="0.5" value="2" data-rn-x aria-label="输入特征 x"></label><label>主路径输出 F(x) <output data-rn-r-out>−0.5</output><input type="range" min="-3" max="3" step="0.5" value="-0.5" data-rn-r aria-label="主路径残差值"></label><button type="button" class="rn-button" data-rn-zero>令 F(x)=0</button><div class="rn-readout" data-rn-block-result aria-live="polite"></div></div></div><p class="vg-caption">滑杆直接指定主路径的示意输出，并未训练卷积权重。原版常见块先相加，再 ReLU；这两步不要混为一谈。</p></div><div class="vg-panel">'+heading('03 · GRADIENT TOY MODEL','多一条直路，梯度会怎样？','简化为相同标量导数，明确看见抵消和放大。')+'<div class="rn-gradient-controls"><label>每个主路径局部导数 a <output data-rn-a-out>−0.2</output><input type="range" min="-1" max="1" step="0.1" value="-0.2" data-rn-a aria-label="主路径局部导数"></label><label>连续块数 L <output data-rn-l-out>12</output><input type="range" min="1" max="30" step="1" value="12" data-rn-l aria-label="连续块数"></label></div><div class="rn-presets" role="group" aria-label="选择导数示例"><button type="button" data-rn-preset="small">小幅修正</button><button type="button" data-rn-preset="cancel">a=−1，完全抵消</button><button type="button" data-rn-preset="grow">正向放大</button></div><div class="rn-gradient-layout"><div data-rn-gradient-chart></div><div class="rn-gradient-values" aria-live="polite"><p><span>普通链 · |a|ᴸ</span><strong data-rn-plain-value></strong></p><p><span>恒等残差链 · |1+a|ᴸ</span><strong data-rn-skip-value></strong></p><div class="rn-readout" data-rn-gradient-note></div></div></div><p class="vg-caption">仅演示相加前的标量链式法则：起始梯度幅度为 1，各层 a 相同，忽略 BN、ReLU 与多通道耦合；不是实际训练结果。纵轴为 log₁₀ 梯度幅度，低于 10⁻¹²（包括 0）显示在底边。</p></div></section>'}
  const anatomy={basic:{label:'BasicBlock',ops:['3×3 Conv + BN + ReLU','3×3 Conv + BN','Add + ReLU'],copy:'ResNet-18/34 的常见基础块。主路径有两层 3×3 卷积；第二层 BN 后先相加，再做块末 ReLU。'},bottleneck:{label:'Bottleneck',ops:['1×1 Conv + BN + ReLU','3×3 Conv + BN + ReLU','1×1 Conv + BN','Add + ReLU'],copy:'ResNet-50/101/152 的常见瓶颈块。中间宽度通常小于最终输出宽度；在较窄通道上做 3×3 卷积，再用 1×1 扩展。'}};
  const quiz=[
    {q:'网络退化可以直接定义为梯度消失。',answer:'false',why:'退化描述加深后训练误差变高；原论文在梯度幅度正常的 BN 网络中也观察到它。'},
    {q:'残差块的 Add 会把 64 通道和 64 通道拼成 128 通道。',answer:'false',why:'Add 是对应元素相加，输出仍是 64 通道；沿通道轴拼接是 Concat。'},
    {q:'输入与主路径输出形状改变时，应先使捷径对齐再相加。',answer:'true',why:'常见方法是带合适步幅的 1×1 投影，必要时接 BN。'},
    {q:'相加前 s=x+F(x) 的局部导数含 1+F′(x)，并不总等于 1。',answer:'true',why:'F′ 可以抵消或放大直接通路；块末激活还会继续影响真实梯度。'},
    {q:'新增残差块即使学到错误修正，也保证不降低准确率。',answer:'false',why:'恒等映射是一种容易表达的解，训练过程和独立数据效果都没有这种保底保证。'},
    {q:'采用残差连接的网络仍然可能过拟合。',answer:'true',why:'残差连接主要帮助优化，不会自动消除数据有限、噪声和泛化问题。'}
  ];
  const forward=['identity = x','out = self.relu(self.bn1(self.conv1(x)))','out = self.bn2(self.conv2(out))','if self.downsample is not None:','    identity = self.downsample(x)','out = out + identity','return self.relu(out)'].join('\n');
  function shapeMarkup(){return '<section class="vgg-playground resnet-playground" data-resnet="shape"><div class="vg-panel">'+heading('04 · SHAPE CHECK','先对齐，再相加','试着把空间减半、通道翻倍；观察捷径要怎样改。')+'<div class="vg-model-switch" role="group" aria-label="选择残差块尺寸"><button type="button" data-rn-shape="same" aria-pressed="true">形状不变</button><button type="button" data-rn-shape="change" aria-pressed="false">空间减半、通道增多</button></div><div class="rn-shape-lanes"><div><span>主路径 F(x)</span><code data-rn-main-shape></code></div><b aria-hidden="true">+</b><div><span>捷径 S(x)</span><code data-rn-shortcut-shape></code></div><b aria-hidden="true">→</b><div><span>相加结果</span><code data-rn-output-shape></code></div></div><button type="button" class="rn-button" data-rn-projection disabled aria-pressed="false">同形状，无需投影</button><p class="rn-readout" data-rn-shape-note aria-live="polite"></p><p class="vg-caption">输入使用 NCHW：[1,64,56,56]。投影示例为 Conv1×1(64→128, stride=2) + BN；图中只追踪形状，不展示卷积计算值。</p></div><div class="vg-panel">'+heading('05 · BLOCK ANATOMY','两种常见残差块','按计算次序看卷积、BN、ReLU 和相加。')+'<div class="vg-model-switch" role="group" aria-label="选择残差块类型"><button type="button" data-rn-anatomy="basic" aria-pressed="true">BasicBlock</button><button type="button" data-rn-anatomy="bottleneck" aria-pressed="false">Bottleneck</button></div><div class="rn-ops" data-rn-ops></div><p class="rn-readout" data-rn-anatomy-note aria-live="polite"></p><details class="rn-code"><summary>对照 BasicBlock 的 forward 顺序</summary><pre><code>'+esc(forward)+'</code></pre><p class="vg-caption">方法逻辑摘解，依赖预先定义的 Conv、BN、ReLU 和 downsample 模块；完整类请看章末 Torchvision 源码链接。</p></details></div><div class="vg-panel">'+heading('06 · CHECK YOUR UNDERSTANDING','六个判断，校准残差直觉','选择后查看解释。')+'<div class="vg-quiz-grid">'+quiz.map((item,i)=>'<article class="vg-quiz-card" data-rn-quiz="'+i+'"><h5>'+esc(item.q)+'</h5><div role="group" aria-label="残差知识第 '+(i+1)+' 题"><button type="button" data-rn-answer="true">正确</button><button type="button" data-rn-answer="false">不正确</button></div><p data-rn-feedback role="status" aria-live="polite"></p></article>').join('')+'</div></div></section>'}
  function updateDiagnosis(root,key){const item=diagnoses[key];root.querySelectorAll('[data-rn-diagnosis]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.rnDiagnosis===key)));root.querySelector('[data-rn-chart]').innerHTML=chartMarkup(item);root.querySelector('[data-rn-diagnosis-title]').textContent=item.title;root.querySelector('[data-rn-diagnosis-copy]').textContent=item.copy;root.querySelector('[data-rn-diagnosis-note]').textContent=item.note}
  const number=n=>Number(n.toFixed(2)).toLocaleString('en-US');
  function updateBlock(root){const x=Number(root.querySelector('[data-rn-x]').value),r=Number(root.querySelector('[data-rn-r]').value),s=x+r,y=Math.max(0,s);root.querySelector('[data-rn-x-out]').textContent=number(x);root.querySelector('[data-rn-r-out]').textContent=number(r);root.querySelector('[data-rn-svg-x]').textContent='x = '+number(x);root.querySelector('[data-rn-svg-r]').textContent='F(x) = '+number(r);root.querySelector('[data-rn-svg-s]').textContent='s = '+number(s);root.querySelector('[data-rn-svg-y]').textContent='ReLU(s) = '+number(y);root.querySelector('[data-rn-block-result]').textContent='相加：'+number(x)+' + ('+number(r)+') = '+number(s)+'；块末 ReLU 输出 '+number(y)+'。'+(r===0?(x<0?'F=0 时相加仍保留 x，但末端 ReLU 会截去负值。':'F=0 时，本例输入非负，整个块输出等于 x。'):'残差可以增加、减小或抵消输入；它不是额外附上的分类答案。')}
  const magnitude=n=>n===0?'0':(n<.001||n>=10000?n.toExponential(2):Number(n.toPrecision(4)).toString());
  function gradientChart(a,l){const clamp=n=>Math.max(-12,Math.min(10,n)),paths=[{name:'普通链',cls:'purple',gain:Math.abs(a)},{name:'残差链',cls:'green',gain:Math.abs(1+a)}];return '<svg viewBox="0 0 430 205" role="img" aria-label="普通链与残差链的梯度幅度对数示意"><path class="rn-axis" d="M40 20V174H408"/>'+[-12,-6,0,6].map(v=>{const y=174-(v+12)*7;return '<path class="rn-grid-line" d="M40 '+y+'H408"/><text x="4" y="'+(y+4)+'">'+v+'</text>'}).join('')+'<text x="6" y="13">log₁₀|梯度|</text><text x="346" y="200">块数 0→'+l+'</text>'+paths.map(p=>'<path class="rn-line rn-'+p.cls+'" d="'+Array.from({length:l+1},(_,i)=>{const log=i===0?0:p.gain===0?-12:i*Math.log10(p.gain);return (i?'L':'M')+(40+i/l*364)+' '+(174-(clamp(log)+12)*7)}).join(' ')+'"/>').join('')+'<text class="rn-label-purple" x="60" y="195">普通链</text><text class="rn-label-green" x="130" y="195">恒等残差链</text></svg>'}
  function updateGradient(root){const a=Number(root.querySelector('[data-rn-a]').value),l=Number(root.querySelector('[data-rn-l]').value),plain=Math.abs(a)**l,skip=Math.abs(1+a)**l;root.querySelector('[data-rn-a-out]').textContent=number(a);root.querySelector('[data-rn-l-out]').textContent=l;root.querySelector('[data-rn-plain-value]').textContent=magnitude(plain);root.querySelector('[data-rn-skip-value]').textContent=magnitude(skip);root.querySelector('[data-rn-gradient-chart]').innerHTML=gradientChart(a,l);root.querySelector('[data-rn-gradient-note]').textContent=a===-1?'a=−1 时，直接项 1 与分支导数 −1 完全抵消，残差链也可变成零梯度。':skip>1?'本例残差链会放大梯度；直接通路并不排除梯度增长或爆炸。':skip===1?'本例残差链幅度保持 1。这来自当前 a=0 的设置，不是所有残差块的性质。':'本例残差链仍会衰减，但比普通链慢。真实网络各层导数不同，不能把此曲线当作训练保证。'}
  function updateShape(root,mode,projection){const change=mode==='change',fixed=change&&projection,main=change?'[1,128,28,28]':'[1,64,56,56]',shortcut=fixed?main:'[1,64,56,56]',valid=!change||fixed;root.dataset.rnShape=mode;root.dataset.rnProjection=String(fixed);root.querySelectorAll('[data-rn-shape]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.rnShape===mode)));root.querySelector('[data-rn-main-shape]').textContent=main;root.querySelector('[data-rn-shortcut-shape]').textContent=shortcut;root.querySelector('[data-rn-output-shape]').textContent=valid?main:'形状不匹配';const button=root.querySelector('[data-rn-projection]');button.disabled=!change;button.setAttribute('aria-pressed',String(fixed));button.textContent=!change?'同形状，无需投影':fixed?'已使用 1×1 投影 · 点击移除':'给捷径加入 1×1 投影';const note=root.querySelector('[data-rn-shape-note]');note.classList.toggle('is-mismatch',!valid);note.textContent=!change?'两条路径形状一致，对应元素相加后仍为 64 通道，空间为 56×56。':fixed?'捷径用 1×1、stride 2 卷积把 64 通道映射为 128 通道并减半空间，现在可逐元素相加。':'主路径已变为 128×28×28，恒等捷径仍是 64×56×56，不能直接 Add。请先为捷径加入投影。'}
  function updateAnatomy(root,key){const data=anatomy[key];root.querySelectorAll('[data-rn-anatomy]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.rnAnatomy===key)));root.querySelector('[data-rn-ops]').innerHTML=data.ops.map(op=>'<span>'+esc(op)+'</span>').join('<i aria-hidden="true">→</i>');root.querySelector('[data-rn-anatomy-note]').textContent=data.copy}
  function initialize(){previous.initialize?.();document.querySelectorAll('[data-resnet]').forEach(root=>{if(root.dataset.resnet==='diagnose')updateDiagnosis(root,'overfit');if(root.dataset.resnet==='block'){updateBlock(root);updateGradient(root)}if(root.dataset.resnet==='shape'){updateShape(root,'same',false);updateAnatomy(root,'basic')}})}
  window.lessonPlaygrounds={render(id,index){if(id==='cnn'){if(index===firstSection)return diagnoseMarkup();if(index===firstSection+1)return blockMarkup();if(index===firstSection+2)return shapeMarkup()}return previous.render?.(id,index)||''},initialize};
  document.addEventListener('click',event=>{const root=event.target.closest('[data-resnet]');if(!root)return;const button=event.target.closest('button');if(!button)return;
    if(button.hasAttribute('data-rn-diagnosis'))updateDiagnosis(root,button.dataset.rnDiagnosis);
    if(button.hasAttribute('data-rn-zero')){root.querySelector('[data-rn-r]').value='0';updateBlock(root)}
    if(button.hasAttribute('data-rn-preset')){const presets={small:[-.2,12],cancel:[-1,12],grow:[.5,20]},values=presets[button.dataset.rnPreset];root.querySelector('[data-rn-a]').value=values[0];root.querySelector('[data-rn-l]').value=values[1];updateGradient(root)}
    if(button.hasAttribute('data-rn-shape'))updateShape(root,button.dataset.rnShape,false);
    if(button.hasAttribute('data-rn-projection'))updateShape(root,root.dataset.rnShape,root.dataset.rnProjection!=='true');
    if(button.hasAttribute('data-rn-anatomy'))updateAnatomy(root,button.dataset.rnAnatomy);
    if(button.hasAttribute('data-rn-answer')){const card=button.closest('[data-rn-quiz]'),item=quiz[Number(card.dataset.rnQuiz)],correct=button.dataset.rnAnswer===item.answer;card.querySelectorAll('[data-rn-answer]').forEach(b=>{b.setAttribute('aria-pressed',String(b===button));b.classList.toggle('is-correct',b===button&&correct);b.classList.toggle('is-wrong',b===button&&!correct)});card.querySelector('[data-rn-feedback]').textContent=(correct?'判断正确。':'再核对一下。')+item.why}
  });
  document.addEventListener('input',event=>{const root=event.target.closest('[data-resnet="block"]');if(!root)return;if(event.target.matches('[data-rn-x],[data-rn-r]'))updateBlock(root);if(event.target.matches('[data-rn-a],[data-rn-l]'))updateGradient(root)});
})();
